import { MutableRefObject, ReactNode } from 'react';
import { WebViewDefinition, WebViewDefinitionUpdateInfo } from '@shared/models/web-view.model';
import { LocalizeKey } from 'platform-bible-utils';

/**
 * Opaque object representing a saved dock layout. Treat this as a black box: it round-trips through
 * `localStorage` and back into the dock layout component, but no consumer should inspect its
 * contents. The renderer's `platform-dock-layout` is the only place that knows the real shape (it
 * is `LayoutBase` from `rc-dock`).
 *
 * Kept opaque here so this shared model does not have to import from `rc-dock`, which keeps
 * `papi.d.ts` (and therefore every extension's typecheck) free of the rc-dock dependency.
 *
 * Eventually, to decouple further from rc-dock, we may implement this as our own layout format and
 * convert to/from `LayoutBase` at the dock layout boundary.
 */
export type LayoutInfo = Record<string, unknown>;

/** Information about a layout change passed from the dock layout to the web view service. */
export type LayoutChangeInfo = {
  /**
   * Whether the most recent layout change closed a web view. When `true`, `webViewDefinition` is
   * the definition of the web view that was just closed.
   */
  didCloseWebView: boolean;
  /**
   * The web view definition associated with the layout change, if the change involved a web view.
   * `undefined` for non-web-view tabs and for changes that don't target a single tab.
   */
  webViewDefinition?: WebViewDefinition;
};

/**
 * Saved information used to recreate a tab.
 *
 * - {@link TabLoader} loads this into {@link TabInfo}
 * - {@link TabSaver} saves {@link TabInfo} into this
 */
export type SavedTabInfo = {
  /**
   * Tab ID - a unique identifier that identifies this tab. If this tab is a WebView, this ID will
   * match the `WebViewDefinition.id`
   */
  id: string;
  /** Type of tab - indicates what kind of built-in tab this info represents */
  tabType: string;
  /** Data needed to load the tab */
  data?: unknown;
};

/** {@link SavedTabInfo.tabType} for web view tabs. A web view tab's id matches its `WebViewId` */
export const TAB_TYPE_WEBVIEW = 'webView';

/**
 * Information that Platform.Bible uses to create a tab in the dock layout.
 *
 * - {@link TabLoader} loads {@link SavedTabInfo} into this
 * - {@link TabSaver} saves this into {@link SavedTabInfo}
 */
export type TabInfo = SavedTabInfo & {
  /**
   * Url of image to show on the title bar of the tab
   *
   * Defaults to the software's standard logo.
   */
  tabIconUrl?: string;
  /**
   * Text to show (or a localizeKey that will automatically be localized) on the title bar of the
   * tab
   */
  tabTitle: string | LocalizeKey;
  /** Text to show when hovering over the title bar of the tab */
  tabTooltip?: string;
  /** The last time (`Date.now()`) the tab was instructed to flash its contents in the UI. */
  flashTriggerTime?: number;
  /** Content to show inside the tab. */
  content: ReactNode;
  /** (optional) Minimum width that the tab can become in CSS `px` units */
  minWidth?: number;
  /** (optional) Minimum height that the tab can become in CSS `px` units */
  minHeight?: number;
  /** Last known focused element. Used for restoring focus in the tab */
  lastFocusedElement?: HTMLElement;
  /**
   * Whether this tab can be closed by the user (shows the tab's close button). Set to `false` for
   * tabs that must always remain open, such as views that are part of the default layout.
   *
   * Note: this default is applied by consumers (treat `undefined` as `true`, e.g. `isClosable ??
   * true`), not enforced by the type.
   *
   * @default true
   */
  isClosable?: boolean;
};

/**
 * Function that takes a {@link SavedTabInfo} and creates a Platform.Bible tab out of it. Each type
 * of tab must provide a {@link TabLoader}.
 *
 * For now all tab creators must do their own data type verification
 */
export type TabLoader = (savedTabInfo: SavedTabInfo) => TabInfo;

/**
 * Function that takes a Platform.Bible tab and creates a saved tab out of it. Each type of tab can
 * provide a {@link TabSaver}. If they do not provide one, the properties added by `TabInfo` are
 * stripped from TabInfo by `saveTabInfoBase` before saving (so it is just a {@link SavedTabInfo}).
 *
 * @param tabInfo The Platform.Bible tab to save
 * @returns The saved tab info for Platform.Bible to persist. If `undefined`, does not save the tab
 */
export type TabSaver = (tabInfo: TabInfo) => SavedTabInfo | undefined;

export const DIRECTION_NEXT_TAB = 'nextTab' as const;
export const DIRECTION_PREVIOUS_TAB = 'previousTab' as const;
export const DIRECTION_NEXT_TAB_OR_GROUP = 'nextTabOrGroup' as const;
export const DIRECTION_PREVIOUS_TAB_OR_GROUP = 'previousTabOrGroup' as const;
export const DIRECTION_NEAR_TAB_OR_NEXT_GROUP = 'nearTabOrNextGroup' as const;
export const DIRECTION_NEXT_TAB_GROUP = 'nextTabGroup' as const;
export const DIRECTION_PREVIOUS_TAB_GROUP = 'previousTabGroup' as const;

/**
 * JSDOC SOURCE DirectionFromTabAdjacent
 *
 * Direction relative to a tab pointing to another tab. Can be used to navigate between tabs in the
 * dock layout. These directions are for navigating to a tab directly before or after the current
 * tab, which may be within the same tab group or may cross tab groups. For directions that can also
 * navigate to tabs specifically in other tab groups, see {@link DirectionFromTab}.
 *
 * Note: In the following descriptions, "forward"/"next" means right in LTR and left in RTL, and
 * "backward"/"previous" means left in LTR and right in RTL
 *
 * - `nextTab` - go forward one tab. If there are no more tabs after this tab in this tab's tab group,
 *   go to the backward-most tab in the next tab group (useful for cycling through all tabs)
 * - `previousTab` - go backward one tab. If there are no more tabs before this tab in this tab's tab
 *   group, go to the forward-most tab in the previous tab group (useful for cycling through all
 *   tabs)
 * - `nextTabOrGroup` - go forward one tab. If there are no more tabs after this tab in this tab's tab
 *   group, go to the active tab in the next tab group
 * - `previousTabOrGroup` - go backward one tab. If there are no more tabs before this tab in this
 *   tab's tab group, go to the active tab in the previous tab group
 * - `nearTabOrNextGroup` - go forward or backward one tab if there is another in the same tab group.
 *   If there are no more tabs in this tab's tab group, go to the active tab in the next tab group
 *   (useful for closing a tab)
 */
export const DIRECTION_FROM_TAB_ADJACENT = Object.freeze([
  DIRECTION_NEXT_TAB,
  DIRECTION_PREVIOUS_TAB,
  DIRECTION_NEXT_TAB_OR_GROUP,
  DIRECTION_PREVIOUS_TAB_OR_GROUP,
  DIRECTION_NEAR_TAB_OR_NEXT_GROUP,
] as const);
/** JSDOC DESTINATION DirectionFromTabAdjacent */
export type DirectionFromTabAdjacent = (typeof DIRECTION_FROM_TAB_ADJACENT)[number];

/**
 * JSDOC SOURCE DirectionFromTab
 *
 * Direction relative to a tab pointing to another tab. Can be used to navigate between tabs in the
 * dock layout. In addition to navigating sequentially between tabs, these directions can navigate
 * to tabs specifically in other tab groups. For directions that only navigate to a tab directly
 * before or after the current tab, see {@link DirectionFromTabAdjacent}.
 *
 * Note: In the following descriptions, "forward"/"next" means right in LTR and left in RTL, and
 * "backward"/"previous" means left in LTR and right in RTL
 *
 * - See {@link DirectionFromTabAdjacent} for directions that look for a tab directly before or after
 *   the current tab, which may be in the same or a different tab group
 * - `nextTabGroup` - go to the active tab in the tab group forward from the tab group this tab is in
 * - `previousTabGroup` - go to the active tab in the tab group backward from the tab group this tab
 *   is in
 */
export const DIRECTION_FROM_TAB = Object.freeze([
  ...DIRECTION_FROM_TAB_ADJACENT,
  DIRECTION_NEXT_TAB_GROUP,
  DIRECTION_PREVIOUS_TAB_GROUP,
] as const);
/** JSDOC DESTINATION DirectionFromTab */
export type DirectionFromTab = (typeof DIRECTION_FROM_TAB)[number];

/**
 * Checks if the specified direction is a valid {@link DirectionFromTab}.
 *
 * @param direction The direction to check
 * @returns True if the direction is a valid {@link DirectionFromTab}, false otherwise
 */
export function isDirectionFromTab(direction: unknown): direction is DirectionFromTab {
  if (!direction) return false;

  // TypeScript's `includes` types are very weird. This code works fine, but TypeScript wants anything
  // passed to `includes` to be of the type of the array for some reason. But that's the whole point here.
  // eslint-disable-next-line no-type-assertion/no-type-assertion
  return DIRECTION_FROM_TAB.includes(direction as DirectionFromTab);
}

/** Information about a tab in a panel */
interface TabLayout {
  type: 'tab';
  /** Id of the parent dock box that the tab belongs to */
  parentTabGroupId?: string;
}

/**
 * Indicates where to display a floating window
 *
 * - `cascade` - place the window a bit below and to the right of the previously created floating
 *   window
 * - `center` - center the window in the dock layout
 */
type FloatPosition = 'cascade' | 'center';

/** The dimensions for a floating tab in CSS `px` units */
export type FloatSize = { width: number; height: number };

/** Information about a floating window */
export interface FloatLayout {
  type: 'float';
  floatSize?: FloatSize;
  /** Where to display the floating window. Defaults to `cascade` */
  position?: FloatPosition;
}

export type PanelDirection =
  | 'left'
  | 'right'
  | 'bottom'
  | 'top'
  // TODO: The following produce a panel but probably aren't useful for panels - IJH 2023-05-5
  | 'before-tab'
  | 'after-tab'
  | 'maximize'
  | 'move'
  | 'active'
  | 'update';

/** Information about a panel */
interface PanelLayout {
  type: 'panel';
  direction?: PanelDirection;
  /** If undefined, it will add in the `direction` relative to the previously added tab. */
  targetTabId?: string;
}

interface ReplaceTabLayout {
  type: 'replace-tab';
  /** The ID of the tab to replace */
  targetTabId: string;
}

/**
 * Information about opening a tab in its own application window.
 *
 * In Simple mode — which is single-window by design — this degrades to `'tab'`: the web view opens
 * as a normal tab in the window the user is working in. An interface mode that cannot be read takes
 * the same degraded path rather than failing the open, so a caller in Power mode can get a tab
 * instead of a window when the mode read fails.
 *
 * It degrades the same way for an open that also passed `existingId: '?'` whose reuse search could
 * not be answered because some window was unreachable. Such an open goes ahead rather than failing,
 * accepting that it may be making a second copy of a web view that already exists somewhere — and a
 * duplicate as a tab is one the user can see and close, where a duplicate as a window takes the
 * screen and OS focus and can hide the original behind it.
 *
 * @experimental This type is unstable and may change or disappear without notice
 */
export interface WindowLayout {
  type: 'window';
}

/** Information about how a Platform.Bible tab fits into the dock layout */
export type Layout = TabLayout | FloatLayout | PanelLayout | ReplaceTabLayout | WindowLayout;

/** Props that are passed to the web view tab component */
export type WebViewTabProps = WebViewDefinition;

/**
 * Async callback invoked by the dock layout component when the layout changes. The web view service
 * implements this to persist the layout and to emit web-view lifecycle events.
 *
 * @param newLayout The changed layout to save.
 * @param currentTabId The tab being changed, if a single tab is identifiable.
 * @param changeInfo Optional metadata about the change (e.g. whether a web view was closed). Only
 *   populated when meaningful — for example, calls from `loadLayout` pass only `newLayout`.
 * @returns Promise that resolves when the service has finished handling the change.
 */
export type OnLayoutChange = (
  newLayout: LayoutInfo,
  currentTabId?: string,
  changeInfo?: LayoutChangeInfo,
) => Promise<void>;

/** Properties related to the dock layout */
export type PapiDockLayout = {
  /**
   * A ref to a function that runs when the layout changes. We set this ref to our
   * {@link onLayoutChange} function
   */
  onLayoutChangeRef: MutableRefObject<OnLayoutChange | undefined>;
  /**
   * Apply a saved layout to the dock. Used by the web view service when restoring layouts from
   * persistent storage. Does not invoke `onLayoutChangeRef`.
   *
   * @param layout Saved layout to apply
   */
  loadLayout: (layout: LayoutInfo) => void;
  /**
   * Find the ID of the first open web view whose `webViewType` matches the one supplied.
   *
   * @param webViewType The web view type to search for
   * @param projectId Optionally limits the search to web views showing a given project
   * @returns The WebViewDefinition of the matching web view, or `undefined` if no web view of that
   *   type is open
   * @experimental The optional `projectId` filter is new; the rest of this member is
   *   long-established.
   */
  findFirstWebViewDefinitionByType: (
    webViewType: string,
    projectId?: string,
  ) => WebViewDefinition | undefined;
  /**
   * Add or update a tab in the layout
   *
   * @param savedTabInfo Info for tab to add or update
   * @param layout Information about where to put a new tab
   * @param shouldBringToFront If true, the tab will be brought to the front and unobscured by other
   *   tabs. Defaults to `true`
   * @returns If tab added, final layout used to display the new tab. If existing tab updated,
   *   `undefined`
   */
  addTabToDock: (
    savedTabInfo: SavedTabInfo,
    layout: Layout,
    shouldBringToFront?: boolean,
  ) => Layout | undefined;
  /**
   * Add or update a webview in the layout
   *
   * @param webView Web view to add or update
   * @param layout Information about where to put a new webview
   * @param shouldBringToFront If true, the tab will be brought to the front and unobscured by other
   *   tabs. Defaults to `true`
   * @returns If WebView added, final layout used to display the new webView. If existing webView
   *   updated, `undefined`
   */
  addWebViewToDock: (
    webView: WebViewTabProps,
    layout: Layout,
    shouldBringToFront?: boolean,
  ) => Layout | undefined;
  /**
   * Remove a tab in the layout
   *
   * @param tabId ID of the tab to remove
   */
  removeTabFromDock: (tabId: string) => boolean;
  /**
   * Float a tab in the layout
   *
   * @param tabId ID of the tab to float
   */
  floatTabById: (tabId: string) => void;
  /**
   * Get the WebView definitions for every open WebView tab across the dock layout.
   *
   * Used by consumers (e.g. ProjectSelector) that need to seed initial state at mount time.
   * `papi.webViews.onDidOpenWebView` does not replay for tabs already open at subscription time, so
   * subscribers that mount after some tabs are already open need this enumeration to bootstrap.
   *
   * @returns Array of WebView definitions, one per currently-open WebView tab. Empty array when the
   *   dock layout has no WebView tabs.
   */
  getAllWebViewDefinitions: () => WebViewDefinition[];
  /**
   * Counts every open tab in the dock layout, of any type — not only web views.
   *
   * Used to tell whether moving a tab out of a window would leave that window with nothing at all,
   * which depends on every tab it holds, not only on its web views.
   *
   * @returns The number of tabs open anywhere in the layout, whatever its docking state
   * @experimental
   */
  getOpenTabCount: () => number;
  /**
   * Gets the WebView definition for the web view with the specified ID
   *
   * @param webViewId The ID of the WebView whose web view definition to get
   * @returns WebView definition with the specified ID or undefined if not found
   */
  getWebViewDefinition: (webViewId: string) => WebViewDefinition | undefined;
  /**
   * Updates the tab with the specified id with the specified properties. No need to have all the
   * tab info; just specify the properties you want to update.
   *
   * WARNING: This does not work well with `tab.data` `WebViewDefinition` information. Use
   * `updateWebViewDefinition` for that instead
   *
   * @param tabId ID of the tab to update
   * @param partialTabInfo Partial tab info to update. Any unspecified properties will stay the same
   * @param shouldBringToFront If true, the tab will flash, will be brought to the front, and will
   *   be unobscured by other tabs. Defaults to `false`
   * @returns Updated tab info or `undefined` if the tab was not found
   * @throws If the item found in the dock layout with the specified ID is not a tab
   */
  updateTabPartial: (
    tabId: string,
    partialTabInfo: Partial<TabInfo>,
    shouldBringToFront?: boolean,
  ) => TabInfo | undefined;
  /**
   * Updates the WebView with the specified ID with the specified properties
   *
   * @param webViewId The ID of the WebView to update
   * @param updateInfo Properties to update on the WebView. Any unspecified properties will stay the
   *   same. Note: `state` will be treated like any other property, meaning it will be overwritten
   *   completely if specified here and the object is referentially different from the current state
   *   object. It is not compared deeply (because we are working across contexts, where `deepEqual`
   *   doesn't always work well) or merged (so we can remove properties from `state`).
   * @param shouldBringToFront If true, the tab will be brought to the front and unobscured by other
   *   tabs. Defaults to `false`
   * @returns True if successfully found the WebView to update; false otherwise
   */
  updateWebViewDefinition: (
    webViewId: string,
    updateInfo: WebViewDefinitionUpdateInfo,
    shouldBringToFront?: boolean,
  ) => boolean;
  /**
   * Gets info for a tab in a direction from the source tab.
   *
   * @param sourceTabId ID of tab to go from to get to destination tab
   * @param direction Direction to go from the source tab to get to the destination tab
   * @returns Info for the destination tab or `undefined` if source tab or destination tab is not
   *   found
   * @throws If the item found in the dock layout with the source tab ID is not a tab
   * @throws If the item found in the dock layout with the destination tab ID is not a tab
   */
  getTabInfoByDirectionFromTab: (
    sourceTabId: string,
    direction: DirectionFromTab,
  ) => TabInfo | undefined;
  /**
   * Gets info for the tab that contains the specified DOM element
   *
   * @param tabElement The DOM element in the tab whose info to get
   * @returns Info for the tab in question or `undefined` if tab is not found
   * @throws If found a tab id in the DOM but there was no corresponding tab info in the dock layout
   */
  getTabInfoByElement: (tabElement: Element) => TabInfo | undefined;
  /**
   * Gets info for the tab with the specified ID
   *
   * @param tabId The ID of the tab whose info to get
   * @returns Info for the tab in question or `undefined` if tab is not found
   * @throws If the item found in the dock layout with the specified ID is not a tab
   */
  getTabInfoById: (tabId: string) => TabInfo | undefined;
  /**
   * Whether this dock holds the tab or tab group with the given ID.
   *
   * Tabs and tab groups are looked up the same way, so one question answers for either kind of ID.
   * Every kind of tab counts, not only WebView tabs.
   *
   * @param tabOrTabGroupId ID of the tab or tab group to look for
   * @returns `true` if this dock holds it, `false` otherwise
   * @experimental
   */
  containsTab: (tabOrTabGroupId: string) => boolean;
  /**
   * Sets an existing tab as the active tab in its tab group, makes sure it is unobscured by other
   * tabs, and sets the document focus in that tab
   *
   * @param tabId ID of the tab to set active and focused
   * @returns `true` if successfully found tab to update, `false` otherwise
   */
  focusTab: (tabId: string) => boolean;
  /**
   * The layout to use as the default layout if the dockLayout doesn't have a layout loaded.
   *
   * TODO: This should be removed and the `testLayout` imported directly in this file once this
   * service is refactored to split the code between processes. The only reason this is passed from
   * `platform-dock-layout.component.tsx` is that we cannot import `testLayout` here since this
   * service is currently all shared code. Refactor should happen in PT-2799
   */
  testLayout: LayoutInfo;
  /**
   * The layout to load when `platform.interfaceMode` is `'simple'`.
   *
   * TODO: Same as `testLayout` — should be imported directly once PT-2799 is resolved.
   */
  simpleLayout: LayoutInfo;
};
